// Node.js Cloud Function: validate and publish to Pub/Sub
const {PubSub} = require('@google-cloud/pubsub');
const pubsub = new PubSub();
exports.validateAndPublish = (req, res) => {
  const evt = req.body; // simple schema check omitted
  const data = Buffer.from(JSON.stringify(evt));
  pubsub.topic('enrich-events').publish(data);
  res.status(200).send('ok');
};
